    [2137]={name="Whittling Knife",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'Rite of Strength'. Pick it over the other reward choices. Starts with Seer Graytongue in Mulgore. Objective: Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache.",zone="Red Cloud Mesa",questName="Rite of Strength",lore="The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."},
