    [2186]={name="Outfitter Belt",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'Skirmish at Echo Ridge'. Pick it over the other reward choices. Starts with Marshal McBride in Elwynn Forest. Objective: Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.",zone="Elwynn Forest",questName="Skirmish at Echo Ridge",lore="Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."},
    [2195]={name="Anvilmar Knife",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'The Troll Cave'. Pick it over the other reward choices. Starts with Grelin Whitebeard in Dun Morogh. Objective: Grelin Whitebeard would like you to kill 14 Frostmane Troll Whelps.",zone="Dun Morogh",questName="The Troll Cave",lore="My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances."},
