    [2218]={name="Craftsman's Dagger",quality=2,ilvl=13,reqLevel=8,sourceType="quest_reward",instructions="Reward from the quest 'A Pilot's Revenge'. Pick it over the other reward choices. The quest is in Dun Morogh. Objective: Kill Mangeclaw.Bring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot.",zone="Dun Morogh",questName="A Pilot's Revenge",lore="Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\" He drove off the beast, but not before it mauled him savagely."},
    [2224]={name="Militia Dagger",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Brotherhood of Thieves'. Pick it over the other reward choices. Starts with Deputy Willem in Elwynn Forest. Objective: Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.",zone="Elwynn Forest",questName="Brotherhood of Thieves",lore="Recently, a new group of thieves has been hanging around Northshire. They call themselves the Defias Brotherhood, and have been seen across the river to the east."},
    [2237]={name="Patched Pants",quality=1,ilvl=10,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Cloth and Leather Armor'. Pick it over the other reward choices. Starts with Marshal Dughan in Elwynn Forest. Objective: Give Sara Timberlain the Stormwind Armor Marker.",zone="Elwynn Forest",questName="Cloth and Leather Armor",lore="For your shrewdness and valor, I have a marker here that is good for one piece of armor. I want you to take it to Sara Timberlain at the Eastvale Logging Camp."},
    [2249]={name="Militia Buckler",quality=1,ilvl=10,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'Riverpaw Gnoll Bounty'. Pick it over the other reward choices. Starts with Deputy Rainer in Elwynn Forest. Objective: Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks.",zone="Elwynn Forest",questName="Riverpaw Gnoll Bounty",lore="Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest. A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder."},
