    [2571]={name="Viny Wrappings",quality=1,ilvl=7,reqLevel=4,sourceType="quest_reward",instructions="Reward from the quest 'Twisted Hatred'. Pick it over the other reward choices. Starts with Tallonkai Swiftroot in Teldrassil. Objective: Kill 8 Befouled Webwoods and bring Xethorr the Wicked's Mature Fel Moss to Tallonkai Swiftroot in Dolanaar.",zone="Teldrassil",questName="Twisted Hatred",lore="I must warn you, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home."},
