    [2817]={name="Soft Leather Tunic",quality=2,ilvl=12,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'Protecting the Herd'. Pick it over the other reward choices. Starts with Rudra Amberstill in Dun Morogh. Objective: Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",zone="Dun Morogh",questName="Protecting the Herd",lore="We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."},
