    [3070]={name="Ensign Cloak",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Bounty on Garrick Padfoot'. Pick it over the other reward choices. Starts with Deputy Willem in Elwynn Forest. Objective: Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.",zone="Elwynn Forest",questName="Bounty on Garrick Padfoot",lore="Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge."},
    [3071]={name="Striking Hatchet",quality=1,ilvl=12,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'At War With The Scarlet Crusade'. Pick it over the other reward choices. Starts with Executor Zygand in Tirisfal Glades. Objective: Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.",zone="Tirisfal Glades",questName="At War With The Scarlet Crusade",lore="Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest. According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew."},
    [3103]={name="Coldridge Hammer",quality=2,ilvl=12,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'Protecting the Herd'. Pick it over the other reward choices. Starts with Rudra Amberstill in Dun Morogh. Objective: Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",zone="Dun Morogh",questName="Protecting the Herd",lore="We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."},
    [3152]={name="Driving Gloves",quality=1,ilvl=9,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Operation Recombobulation'. Pick it over the other reward choices. Starts with Razzle Sprysprocket in Dun Morogh. Objective: Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.",zone="Dun Morogh",questName="Operation Recombobulation",lore="Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."},
    [3153]={name="Oil-stained Cloak",quality=1,ilvl=9,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Operation Recombobulation'. Pick it over the other reward choices. Starts with Razzle Sprysprocket in Dun Morogh. Objective: Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.",zone="Dun Morogh",questName="Operation Recombobulation",lore="Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."},
    [3160]={name="Ironplate Buckler",quality=2,ilvl=15,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Filthy Paws'. Pick it over the other reward choices.",zone="Loch Modan",questName="Filthy Paws",lore="The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!"},
