    [3435]={name="Zombie Skin Bracers",quality=1,ilvl=8,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Proof of Demise'. Pick it over the other reward choices. Starts with Deathguard Burgess in Tirisfal Glades. Objective: Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.",zone="Tirisfal Glades",questName="Proof of Demise",lore="Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them."},
    [3439]={name="Zombie Skin Boots",quality=1,ilvl=8,reqLevel=4,sourceType="quest_reward",instructions="Reward from the quest 'Graverobbers'. Pick it over the other reward choices. Starts with Magistrate Sevren in Tirisfal Glades. Objective: Kill Rot Hide Graverobbers and Rot Hide Mongrels. Bring 8 Embalming Ichors to Magistrate Sevren in Brill.",zone="Tirisfal Glades",questName="Graverobbers",lore="The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."},
    [3440]={name="Bonecracker",quality=2,ilvl=13,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'The Family Crypt'. Pick it over the other reward choices. Starts with Magistrate Sevren in Tirisfal Glades. Objective: Kill 8 Wailing Ancestors and 8 Rotting Ancestors.Kill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.",zone="Tirisfal Glades",questName="The Family Crypt",lore="The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."},
    [3443]={name="Ceremonial Tomahawk",quality=1,ilvl=10,reqLevel=4,sourceType="quest_reward",instructions="Reward from the quest 'Wildmane Cleansing'. Pick it over the other reward choices. Starts with Mull Thunderhorn in Mulgore. Objective: Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.",zone="Mulgore",questName="Wildmane Cleansing",lore="Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young. The Wildmane Totem is made, and your last task lies ahead."},
    [3444]={name="Tiller's Vest",quality=1,ilvl=11,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: Maggot Eye'. Pick it over the other reward choices. The quest is in Tirisfal Glades. Objective: Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.",zone="Tirisfal Glades",questName="Wanted: Maggot Eye",lore="Wanted: Maggot Eye! A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken. This despicable villain has been stealing corpses for use by the Lich King's army."},
    [3445]={name="Ceremonial Knife",quality=1,ilvl=12,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'At War With The Scarlet Crusade'. Pick it over the other reward choices. Starts with Executor Zygand in Tirisfal Glades. Objective: Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.",zone="Tirisfal Glades",questName="At War With The Scarlet Crusade",lore="Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest. According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew."},
    [3446]={name="Darkwood Staff",quality=2,ilvl=13,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'The Family Crypt'. Pick it over the other reward choices. Starts with Magistrate Sevren in Tirisfal Glades. Objective: Kill 8 Wailing Ancestors and 8 Rotting Ancestors.Kill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.",zone="Tirisfal Glades",questName="The Family Crypt",lore="The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."},
    [3451]={name="Nightglow Concoction",quality=2,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'A Recipe For Death'. Pick it over the other reward choices. Starts with Apothecary Renferrel in Silverpine Forest. Objective: Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.",zone="Silverpine Forest",questName="A Recipe For Death",lore="According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."},
    [3488]={name="Copper Battle Axe",quality=2,ilvl=13,reqLevel=8,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [3570]={name="Bonegrinding Pestle",quality=2,ilvl=16,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Arugal's Folly'. Pick it over the other reward choices. Starts with Dalar Dawnweaver in Silverpine Forest. Objective: Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher.",zone="Silverpine Forest",questName="Arugal's Folly",lore="As my understanding of Arugal's magic grows so does my disdain for the hapless fool. I am close to completing my research on his so called remedy."},
    [3578]={name="Harvester's Pants",quality=2,ilvl=15,reqLevel=8,sourceType="quest_reward",instructions="Reward from the quest 'The Killing Fields'. Pick it over the other reward choices. Starts with Farmer Saldean in Westfall. Objective: Farmer Saldean wants you to kill 20 Harvest Watchers.",zone="Westfall",questName="The Killing Fields",lore="Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though!"},
    [3582]={name="Acidproof Cloak",quality=2,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'A Recipe For Death'. Pick it over the other reward choices. Starts with Apothecary Renferrel in Silverpine Forest. Objective: Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.",zone="Silverpine Forest",questName="A Recipe For Death",lore="According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."},
